def linear_getViewer(**_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, status, credential_id=None, organization_id=None, meta=None, started=None):
        _ensure_request_log()
        logs = _load("request_logs.json")
        ended = time.time()
        latency_ms = None if started is None else int(round((ended - started) * 1000))
        row = {
            "id": f"lin_req_{int(ended * 1000)}",
            "endpoint": endpoint,
            "status": status,
            "credential_id": credential_id,
            "organization_id": organization_id,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    started = time.time()
    try:
        accounts = _load("accounts.json")
        organizations = _load("organizations.json")

        # Resolve "current auth context" by finding a usable viewer+org combination.
        viewers = [
            a for a in accounts
            if isinstance(a, dict)
            and a.get("entity_type") == "user"
            and a.get("status") == "active"
            and a.get("is_viewer") is True
            and isinstance(a.get("organization_id"), str)
        ]
        # Prefer viewer whose org is active; otherwise allow suspended for reads, but viewer itself must be active.
        chosen = None
        chosen_org = None
        org_by_id = {o.get("id"): o for o in organizations if isinstance(o, dict) and isinstance(o.get("id"), str)}
        for v in viewers:
            org = org_by_id.get(v.get("organization_id"))
            if org and org.get("status") == "active":
                chosen, chosen_org = v, org
                break
        if chosen is None and viewers:
            # allow suspended org context for read
            v = viewers[0]
            org = org_by_id.get(v.get("organization_id"))
            if org and org.get("status") in ("suspended", "active"):
                chosen, chosen_org = v, org

        if chosen is None:
            _log("linear_getViewer", "error", meta={"code": "UNAUTHORIZED"}, started=started)
            return _err("UNAUTHORIZED", "Missing, invalid, or expired token for Linear viewer context.")

        body = {
            "viewer": chosen,
            "organization": chosen_org,
        }
        _log("linear_getViewer", "ok", organization_id=chosen.get("organization_id"), started=started)
        return body
    except Exception as e:
        _log("linear_getViewer", "error", meta={"code": "INTERNAL_ERROR"}, started=started)
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

def linear_getOrganization(organizationId=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, status, credential_id=None, organization_id=None, meta=None, started=None):
        _ensure_request_log()
        logs = _load("request_logs.json")
        ended = time.time()
        latency_ms = None if started is None else int(round((ended - started) * 1000))
        row = {
            "id": f"lin_req_{int(ended * 1000)}",
            "endpoint": endpoint,
            "status": status,
            "credential_id": credential_id,
            "organization_id": organization_id,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    started = time.time()
    try:
        if organizationId is not None:
            if not isinstance(organizationId, str):
                _log("linear_getOrganization", "error", meta={"code": "VALIDATION_ERROR"}, started=started)
                return _err("VALIDATION_ERROR", "organizationId must be a string.")
            if not re.match(r"^lin_org_[0-9A-Z]{18,}$", organizationId):
                _log("linear_getOrganization", "error", meta={"code": "VALIDATION_ERROR"}, started=started)
                return _err("VALIDATION_ERROR", "organizationId is malformed.")

        accounts = _load("accounts.json")
        organizations = _load("organizations.json")

        # Resolve viewer/org context (ambient auth).
        viewers = [
            a for a in accounts
            if isinstance(a, dict)
            and a.get("entity_type") == "user"
            and a.get("status") == "active"
            and a.get("is_viewer") is True
            and isinstance(a.get("organization_id"), str)
        ]
        if not viewers:
            _log("linear_getOrganization", "error", meta={"code": "UNAUTHORIZED"}, started=started)
            return _err("UNAUTHORIZED", "Missing, invalid, or expired token for Linear viewer context.")

        org_by_id = {o.get("id"): o for o in organizations if isinstance(o, dict) and isinstance(o.get("id"), str)}

        current_org = None
        for v in viewers:
            o = org_by_id.get(v.get("organization_id"))
            if o:
                current_org = o
                break

        if current_org is None:
            _log("linear_getOrganization", "error", meta={"code": "UNAUTHORIZED"}, started=started)
            return _err("UNAUTHORIZED", "No accessible organization found for viewer.")

        target_id = organizationId or current_org.get("id")
        target = org_by_id.get(target_id)
        if not target or target.get("status") == "deleted":
            _log("linear_getOrganization", "error", meta={"code": "NOT_FOUND"}, started=started)
            return _err("NOT_FOUND", "Organization not found.")

        # Membership visibility: viewer must belong to the org.
        if target_id != current_org.get("id"):
            _log("linear_getOrganization", "error", meta={"code": "UNAUTHORIZED"}, started=started)
            return _err("UNAUTHORIZED", "Not permitted to access the requested organization.")

        # Business rule: return active org for current auth context; if suspended, reads may still return it.
        _log("linear_getOrganization", "ok", organization_id=target_id, started=started)
        return {"organization": target}
    except Exception as e:
        _log("linear_getOrganization", "error", meta={"code": "INTERNAL_ERROR"}, started=started)
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

def linear_getUsers(organizationId=None, teamId=None, includeArchived=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_getUsers"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status, organization_id=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "lin_req_" + uuid.uuid4().hex.upper(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "credential_id": None,
            "organization_id": organization_id,
        }
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    org_pat = re.compile(r"^lin_org_[0-9A-Z]{18,}$")
    acct_pat = re.compile(r"^lin_acct_[0-9A-Z]{18,}$")

    # Validate types/ranges; be permissive about vendor pattern mismatches observed in audit by treating them as NOT_FOUND later.
    if organizationId is not None and not isinstance(organizationId, str):
        _log("error", message="organizationId type")
        return _err("VALIDATION_ERROR", "organizationId must be a string.")
    if teamId is not None and not isinstance(teamId, str):
        _log("error", message="teamId type")
        return _err("VALIDATION_ERROR", "teamId must be a string.")
    if includeArchived is not None and not isinstance(includeArchived, bool):
        _log("error", message="includeArchived type")
        return _err("VALIDATION_ERROR", "includeArchived must be a boolean.")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 250):
        _log("error", message="limit range")
        return _err("VALIDATION_ERROR", "limit is out of range (1-250).")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", message="cursor type")
        return _err("VALIDATION_ERROR", "cursor is malformed.")

    orgs = _load("organizations.json")
    accts = _load("accounts.json")
    if not isinstance(orgs, list) or not isinstance(accts, list):
        _log("error", message="datastore corrupt")
        return _err("CONFLICT", "Datastore is in an unexpected format.")

    # Resolve organization context:
    # - If organizationId provided, use it if exists (active/suspended allowed for read); otherwise NOT_FOUND.
    # - Else derive from a viewer row (active).
    org_row = None
    if organizationId is not None:
        if org_pat.match(organizationId) is None:
            # Treat malformed as NOT_FOUND for compatibility with observed callers passing org IDs into teamId etc.
            _log("error", message="organizationId malformed")
            return _err("NOT_FOUND", "Organization not found.")
        org_row = next((o for o in orgs if isinstance(o, dict) and o.get("id") == organizationId and o.get("status") in ("active", "suspended")), None)
        if org_row is None:
            _log("error", organization_id=organizationId, message="organization not found")
            return _err("NOT_FOUND", "Organization not found.")
    else:
        viewer = next((a for a in accts if isinstance(a, dict) and a.get("entity_type") == "user" and a.get("is_viewer") is True and a.get("status") == "active"), None)
        if viewer is None:
            _log("error", message="no viewer context")
            return _err("UNAUTHORIZED", "No authenticated viewer context available.")
        org_row = next((o for o in orgs if isinstance(o, dict) and o.get("id") == viewer.get("organization_id") and o.get("status") in ("active", "suspended")), None)
        if org_row is None:
            _log("error", organization_id=viewer.get("organization_id"), message="organization missing for viewer")
            return _err("UNAUTHORIZED", "No accessible organization context available.")

    org_id = org_row.get("id")

    # Optional team scoping:
    team_row = None
    if teamId is not None:
        if acct_pat.match(teamId) is None:
            _log("error", organization_id=org_id, message="teamId malformed treated as not found")
            return _err("NOT_FOUND", "Team not found.")
        team_row = next((a for a in accts if isinstance(a, dict) and a.get("id") == teamId and a.get("entity_type") == "team" and a.get("organization_id") == org_id and a.get("status") != "deleted"), None)
        if team_row is None:
            _log("error", organization_id=org_id, message="team not found")
            return _err("NOT_FOUND", "Team not found.")

    # Build user list
    users = [a for a in accts if isinstance(a, dict) and a.get("entity_type") == "user" and a.get("organization_id") == org_id and a.get("status") != "deleted"]
    if not includeArchived:
        users = [u for u in users if u.get("status") == "active"]

    if team_row is not None:
        memberships = [m for m in accts if isinstance(m, dict) and m.get("entity_type") == "team_membership" and m.get("team_id") == teamId and m.get("status") != "deleted"]
        member_user_ids = {m.get("user_id") for m in memberships if m.get("user_id")}
        users = [u for u in users if u.get("id") in member_user_ids]

    # Deterministic order for pagination (name, then id)
    def _sort_key(u):
        nm = u.get("name") or ""
        em = u.get("email") or ""
        return (nm.lower(), em.lower(), u.get("id") or "")

    users.sort(key=_sort_key)

    # Cursor pagination (cursor is last seen id)
    start_idx = 0
    if cursor:
        for i, u in enumerate(users):
            if u.get("id") == cursor:
                start_idx = i + 1
                break

    lim = 50 if limit is None else limit
    page = users[start_idx:start_idx + lim]
    next_cursor = page[-1].get("id") if (start_idx + lim) < len(users) and page else None

    resp = {
        "nodes": page,
        "page_info": {
            "total": len(users),
            "limit": lim,
            "has_more": (start_idx + lim) < len(users),
            "next_cursor": next_cursor,
        },
    }
    _log("ok", organization_id=org_id)
    return resp

