def linear_getTeams(organizationId=None, includeArchived=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_getTeams"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"lin_req_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        logs.append(row)
        _save("request_log.json", logs)

    # Validate inputs
    if organizationId is not None:
        if not isinstance(organizationId, str) or re.match(r"^lin_org_[0-9A-Z]{18,}$", organizationId) is None:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "organizationId is malformed.")
    if includeArchived is not None and not isinstance(includeArchived, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "includeArchived must be a boolean.")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 250:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit is out of range (1-250).")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor is malformed.")

    orgs = _load("organizations.json")
    accts = _load("accounts.json")

    # Resolve current org context (ambient auth): pick an org that has an active viewer user.
    viewer_by_org = {}
    if isinstance(accts, list):
        for a in accts:
            if isinstance(a, dict) and a.get("entity_type") == "user" and a.get("status") == "active" and a.get("is_viewer") is True:
                oid = a.get("organization_id")
                if isinstance(oid, str):
                    viewer_by_org[oid] = a

    org_map = {o.get("id"): o for o in orgs if isinstance(o, dict) and isinstance(o.get("id"), str)}
    chosen_org = None
    if organizationId:
        chosen_org = org_map.get(organizationId)
        if not chosen_org:
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Organization not found.")
        # Require it to be visible in this ambient context (has viewer)
        if organizationId not in viewer_by_org:
            _log("error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Missing/invalid authentication for organization.")
    else:
        # Choose an org with viewer; prefer active orgs but allow suspended for read tools
        candidates = []
        for oid, v in viewer_by_org.items():
            org = org_map.get(oid)
            if not org:
                continue
            st = org.get("status")
            if st in ("active", "suspended"):
                candidates.append((0 if st == "active" else 1, org.get("created_at") or "", oid))
        if not candidates:
            _log("error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Missing/invalid authentication.")
        candidates.sort()
        chosen_org = org_map[candidates[0][2]]

    oid = chosen_org.get("id")

    inc_arch = bool(includeArchived) if includeArchived is not None else False
    lim = limit if limit is not None else 50

    # Cursor is an opaque offset cursor: "offset:<int>"
    offset = 0
    if cursor:
        if not cursor.startswith("offset:"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is malformed.")
        try:
            offset = int(cursor.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is malformed.")

    teams = []
    for a in accts if isinstance(accts, list) else []:
        if not isinstance(a, dict):
            continue
        if a.get("entity_type") != "team":
            continue
        if a.get("organization_id") != oid:
            continue
        st = a.get("status")
        if st == "deleted":
            continue
        if st == "archived" and not inc_arch:
            continue
        if st == "active" or (inc_arch and st == "archived"):
            teams.append(a)

    # Stable sort: by name then id
    teams.sort(key=lambda r: ((r.get("name") or "").lower(), r.get("id") or ""))

    total = len(teams)
    page = teams[offset: offset + lim]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = f"offset:{next_off}" if has_more else None

    _log("ok")
    return {
        "organization": chosen_org,
        "nodes": page,
        "pageInfo": {"limit": lim, "cursor": cursor, "nextCursor": next_cursor, "hasMore": has_more},
        "total": total,
    }

def linear_getWorkflowStates(teamId, includeArchived=None, limit=None, cursor=None, **_extra):
