            "timestamp": _now_iso(),
            "credential_id": None,
            "organization_id": organization_id,
        }
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    acct_pat = re.compile(r"^lin_acct_[0-9A-Z]{18,}$")

    if not isinstance(teamId, str):
        _log("error", message="teamId type")
        return _err("VALIDATION_ERROR", "teamId must be a string.")
    # Relax: treat pattern mismatch as not found (audit passed org ids mistakenly)
    if acct_pat.match(teamId) is None:
        _log("error", message="teamId malformed treated as not found")
        return _err("NOT_FOUND", "Team not found.")
    if includeArchived is not None and not isinstance(includeArchived, bool):
        _log("error", message="includeArchived type")
        return _err("VALIDATION_ERROR", "includeArchived must be a boolean.")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 250):
        _log("error", message="limit range")
        return _err("VALIDATION_ERROR", "limit is out of range (1-250).")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", message="cursor type")
        return _err("VALIDATION_ERROR", "cursor is malformed.")

    accts = _load("accounts.json")
    if not isinstance(accts, list):
        _log("error", message="datastore corrupt")
        return _err("CONFLICT", "Datastore is in an unexpected format.")

    team_row = next((a for a in accts if isinstance(a, dict) and a.get("id") == teamId and a.get("entity_type") == "team" and a.get("status") != "deleted"), None)
    if team_row is None:
        _log("error", message="team not found")
        return _err("NOT_FOUND", "Team not found.")
    org_id = team_row.get("organization_id")

    states = [a for a in accts if isinstance(a, dict) and a.get("entity_type") == "workflow_state" and a.get("team_id") == teamId and a.get("status") != "deleted"]
    if not includeArchived:
        states = [s for s in states if s.get("status") == "active"]

    # Order by position asc
    def _pos(v):
        p = v.get("position")
        return p if isinstance(p, int) else 10**9

    states.sort(key=lambda s: (_pos(s), (s.get("name") or "").lower(), s.get("id") or ""))

    start_idx = 0
    if cursor:
        for i, s in enumerate(states):
            if s.get("id") == cursor:
                start_idx = i + 1
                break

    lim = 50 if limit is None else limit
    page = states[start_idx:start_idx + lim]
    next_cursor = page[-1].get("id") if (start_idx + lim) < len(states) and page else None

    resp = {
        "nodes": page,
        "page_info": {
            "total": len(states),
            "limit": lim,
            "has_more": (start_idx + lim) < len(states),
            "next_cursor": next_cursor,
        },
    }
    _log("ok", organization_id=org_id)
    return resp

def linear_getProjects(organizationId=None, teamId=None, status=None, startAtFrom=None, startAtTo=None, endAtFrom=None, endAtTo=None, query=None, sortBy=None, sortOrder=None, limit=None, cursor=None, **_extra):
