        row = {
            "id": "lin_req_" + uuid.uuid4().hex.upper(),
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "credential_id": None,
            "organization_id": organization_id,
        }
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string.")
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string.")

    org_pat = re.compile(r"^lin_org_[0-9A-Z]{18,}$")
    acct_pat = re.compile(r"^lin_acct_[0-9A-Z]{18,}$")
    allowed_status = {"active", "planned", "completed", "canceled", "archived", "deleted"}
    allowed_sort_by = {"createdAt", "updatedAt", "startAt", "endAt", "name"}
    allowed_sort_order = {"asc", "desc"}

    if organizationId is not None and not isinstance(organizationId, str):
        _log("error", message="organizationId type")
        return _err("VALIDATION_ERROR", "organizationId must be a string.")
    if teamId is not None and not isinstance(teamId, str):
        _log("error", message="teamId type")
        return _err("VALIDATION_ERROR", "teamId must be a string.")
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("error", message="status enum")
        return _err("VALIDATION_ERROR", "status is invalid.")
    if query is not None and not isinstance(query, str):
        _log("error", message="query type")
        return _err("VALIDATION_ERROR", "query must be a string.")
    if sortBy is not None and (not isinstance(sortBy, str) or sortBy not in allowed_sort_by):
        _log("error", message="sortBy enum")
        return _err("VALIDATION_ERROR", "sortBy is invalid.")
    if sortOrder is not None and (not isinstance(sortOrder, str) or sortOrder not in allowed_sort_order):
        _log("error", message="sortOrder enum")
        return _err("VALIDATION_ERROR", "sortOrder is invalid.")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 250):
        _log("error", message="limit range")
        return _err("VALIDATION_ERROR", "limit is out of range (1-250).")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", message="cursor type")
        return _err("VALIDATION_ERROR", "cursor is malformed.")

    dt_saf, e = _parse_dt(startAtFrom, "startAtFrom")
    if e:
        _log("error", message="startAtFrom parse")
        return e
    dt_sat, e = _parse_dt(startAtTo, "startAtTo")
    if e:
        _log("error", message="startAtTo parse")
        return e
    dt_eaf, e = _parse_dt(endAtFrom, "endAtFrom")
    if e:
        _log("error", message="endAtFrom parse")
        return e
    dt_eat, e = _parse_dt(endAtTo, "endAtTo")
    if e:
        _log("error", message="endAtTo parse")
        return e

    orgs = _load("organizations.json")
    accts = _load("accounts.json")
    planning = _load("planning.json")
    if not isinstance(orgs, list) or not isinstance(accts, list) or not isinstance(planning, list):
        _log("error", message="datastore corrupt")
        return _err("CONFLICT", "Datastore is in an unexpected format.")

    org_row = None
    if organizationId is not None:
        if org_pat.match(organizationId) is None:
            _log("error", message="organizationId malformed treated as not found")
            return _err("NOT_FOUND", "Organization not found.")
        org_row = next((o for o in orgs if isinstance(o, dict) and o.get("id") == organizationId and o.get("status") in ("active", "suspended")), None)
        if org_row is None:
            _log("error", organization_id=organizationId, message="organization not found")
            return _err("NOT_FOUND", "Organization not found.")
    else:
        viewer = next((a for a in accts if isinstance(a, dict) and a.get("entity_type") == "user" and a.get("is_viewer") is True and a.get("status") == "active"), None)
        if viewer is None:
            _log("error", message="no viewer context")
            return _err("UNAUTHORIZED", "No authenticated viewer context available.")
        org_row = next((o for o in orgs if isinstance(o, dict) and o.get("id") == viewer.get("organization_id") and o.get("status") in ("active", "suspended")), None)
        if org_row is None:
            _log("error", organization_id=viewer.get("organization_id"), message="organization missing for viewer")
            return _err("UNAUTHORIZED", "No accessible organization context available.")

    org_id = org_row.get("id")

    team_row = None
    if teamId is not None:
        if acct_pat.match(teamId) is None:
            _log("error", organization_id=org_id, message="teamId malformed treated as not found")
            return _err("NOT_FOUND", "Team not found.")
        team_row = next((a for a in accts if isinstance(a, dict) and a.get("id") == teamId and a.get("entity_type") == "team" and a.get("organization_id") == org_id and a.get("status") != "deleted"), None)
        if team_row is None:
            _log("error", organization_id=org_id, message="team not found")
            return _err("NOT_FOUND", "Team not found.")

    # Projects are planning rows entity_type='project'
    projects = [p for p in planning if isinstance(p, dict) and p.get("entity_type") == "project" and p.get("organization_id") == org_id and p.get("status") != "deleted"]
    if team_row is not None:
        # Schema doesn't store team_id for project, but tool claims team-owned; accept filtering by keeping those whose
        # description mentions team or, if present, team_id field (future-proof). If no team_id field exists, treat as no-op.
        projects = [p for p in projects if (p.get("team_id") == teamId) or ("team_id" not in p)]

    if status is not None:
        projects = [p for p in projects if p.get("status") == status]

    q = (query or "").strip().lower()
    if q:
        def _hay(p):
            return ((p.get("name") or "") + "\n" + (p.get("description") or "")).lower()
        projects = [p for p in projects if q in _hay(p)]

    def _dt_from_iso(s):
        if not isinstance(s, str):
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _in_range(p):
        sa = _dt_from_iso(p.get("start_at"))
        ea = _dt_from_iso(p.get("end_at"))
        if dt_saf and sa and sa < dt_saf:
            return False
        if dt_sat and sa and sa > dt_sat:
            return False
        if dt_eaf and ea and ea < dt_eaf:
            return False
        if dt_eat and ea and ea > dt_eat:
            return False
        return True

    projects = [p for p in projects if _in_range(p)]

    sortBy_eff = sortBy or "updatedAt"
    sortOrder_eff = sortOrder or "desc"

    def _sortval(p):
        if sortBy_eff == "createdAt":
            return p.get("created_at") or ""
        if sortBy_eff == "updatedAt":
            return p.get("updated_at") or ""
        if sortBy_eff == "startAt":
            return p.get("start_at") or ""
        if sortBy_eff == "endAt":
            return p.get("end_at") or ""
        if sortBy_eff == "name":
            return (p.get("name") or "").lower()
        return p.get("updated_at") or ""

    projects.sort(key=lambda p: (_sortval(p), p.get("id") or ""), reverse=(sortOrder_eff == "desc"))

    start_idx = 0
    if cursor:
        for i, p in enumerate(projects):
            if p.get("id") == cursor:
                start_idx = i + 1
                break

    lim = 50 if limit is None else limit
    page = projects[start_idx:start_idx + lim]
    next_cursor = page[-1].get("id") if (start_idx + lim) < len(projects) and page else None

    resp = {
        "nodes": page,
        "page_info": {
            "total": len(projects),
            "limit": lim,
            "has_more": (start_idx + lim) < len(projects),
            "next_cursor": next_cursor,
        },
    }
    _log("ok", organization_id=org_id)
    return resp

def linear_createProject(organizationId=None, teamId=None, name=None, description=None, startAt=None, endAt=None, status=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_createProject"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_s, organization_id=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "lin_req_" + uuid.uuid4().hex.upper(),
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "credential_id": None,
            "organization_id": organization_id,
        }
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(s, field_name):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 date-time string.")
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 date-time string.")

    org_pat = re.compile(r"^lin_org_[0-9A-Z]{18,}$")
    acct_pat = re.compile(r"^lin_acct_[0-9A-Z]{18,}$")
    allowed_status = {"active", "planned", "completed", "canceled", "archived"}

    # Validate inputs (relax pattern: for teamId, treat pattern mismatch as NOT_FOUND to match real behavior with bad inputs)
    if teamId is None or not isinstance(teamId, str):
        _log("error", message="teamId required")
        return _err("VALIDATION_ERROR", "teamId is required.")
    if name is None or not isinstance(name, str) or name.strip() == "":
        _log("error", message="name required")
        return _err("VALIDATION_ERROR", "name is required.")

    if organizationId is not None and not isinstance(organizationId, str):
        _log("error", message="organizationId type")
        return _err("VALIDATION_ERROR", "organizationId must be a string.")

    if description is not None and not isinstance(description, str):
        _log("error", message="description type")
        return _err("VALIDATION_ERROR", "description must be a string.")
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("error", message="status enum")
        return _err("VALIDATION_ERROR", "status is invalid.")

    dt_start, e = _parse_dt(startAt, "startAt")
    if e:
        _log("error", message="startAt parse")
        return e
    dt_end, e = _parse_dt(endAt, "endAt")
    if e:
        _log("error", message="endAt parse")
        return e

    orgs = _load("organizations.json")
    accts = _load("accounts.json")
    planning = _load("planning.json")
    if not isinstance(orgs, list) or not isinstance(accts, list) or not isinstance(planning, list):
        _log("error", message="datastore corrupt")
        return _err("CONFLICT", "Datastore is in an unexpected format.")

    # Resolve team + implied org (teamId is authoritative)
    if acct_pat.match(teamId) is None:
        _log("error", message="teamId malformed treated as not found")
        return _err("NOT_FOUND", "Team not found.")
    team_row = next((a for a in accts if isinstance(a, dict) and a.get("id") == teamId and a.get("entity_type") == "team" and a.get("status") != "deleted"), None)
    if team_row is None:
        _log("error", message="team not found")
        return _err("NOT_FOUND", "Team not found.")

    org_id_from_team = team_row.get("organization_id")
    if organizationId is not None:
        if org_pat.match(organizationId) is None:
            _log("error", message="organizationId malformed treated as not found")
            return _err("NOT_FOUND", "Organization not found.")
        if organizationId != org_id_from_team:
            _log("error", organization_id=org_id_from_team, message="team not in organization")
            return _err("NOT_FOUND", "Organization not found.")
        org_id = organizationId
    else:
        org_id = org_id_from_team

    org_row = next((o for o in orgs if isinstance(o, dict) and o.get("id") == org_id), None)
    if org_row is None or org_row.get("status") in ("deleted",):
        _log("error", organization_id=org_id, message="organization not found")
        return _err("NOT_FOUND", "Organization not found.")
    if org_row.get("status") != "active":
        _log("error", organization_id=org_id, message="org not active for write")
        return _err("UNAUTHORIZED", "Organization is not active.")

    # Uniqueness: unique(organization_id, entity_type, name) where entity_type='project' and status<>'deleted'
    for p in planning:
        if isinstance(p, dict) and p.get("entity_type") == "project" and p.get("organization_id") == org_id and p.get("status") != "deleted" and (p.get("name") or "") == name:
            _log("error", organization_id=org_id, message="project name conflict")
            return _err("CONFLICT", "A project with this name already exists in the organization.")

    now = _now_iso()
    new_id = "lin_plan_" + uuid.uuid4().hex.upper()
    proj = {
        "id": new_id,
        "organization_id": org_id,
        "entity_type": "project",
        "status": status or "planned",
        "team_id": teamId,  # store owning team for later filtering even if schema doesn't require it
        "name": name,
        "description": description,
        "start_at": dt_start.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z") if dt_start else None,
        "end_at": dt_end.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z") if dt_end else None,
        "project_id": None,
        "cycle_id": None,
        "issue_id": None,
        "created_at": now,
        "updated_at": now,
    }
    planning.append(proj)
    _save("planning.json", planning)
    _log("ok", organization_id=org_id)
    return {"project": proj}

