                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt_utc = dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
            return dt_utc.isoformat().replace("+00:00", "Z"), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} is not a valid ISO 8601 date-time")

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _log(endpoint, status, org_id=None, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"lin_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "organization_id": org_id,
            "credential_id": credential_id,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    endpoint = "linear_updateProject"

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^lin_plan_[0-9A-Z]{18,}$", project_id):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "project_id is malformed")

    if name is not None and (not isinstance(name, str) or name == ""):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if description is not None and not isinstance(description, str):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "description must be a string")
    allowed_status = {"active", "planned", "completed", "canceled", "archived", "deleted"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "status is invalid")
    if team_id is not None:
        if not isinstance(team_id, str) or not re.match(r"^lin_acct_[0-9A-Z]{18,}$", team_id):
            _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "team_id is malformed")

    start_iso, e = _parse_dt(start_at, "start_at")
    if e:
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return e
    end_iso, e = _parse_dt(end_at, "end_at")
    if e:
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return e
    if start_iso is not None and end_iso is not None:
        # compare
        try:
            sdt = datetime.datetime.fromisoformat(start_iso.replace("Z", "+00:00"))
            edt = datetime.datetime.fromisoformat(end_iso.replace("Z", "+00:00"))
            if not (edt > sdt):
                _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "end_at must be after start_at")
        except ValueError:
            _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Malformed start_at/end_at")

    orgs = _load("organizations.json")
    accts = _load("accounts.json")
    planning = _load("planning.json")

    # Resolve auth context (ambient): pick an org with an active viewer user
    viewer = None
    org = None
    for a in accts:
        if a.get("entity_type") == "user" and a.get("is_viewer") is True and a.get("status") == "active":
            oid = a.get("organization_id")
            o = next((x for x in orgs if x.get("id") == oid), None)
            if o and o.get("status") in ("active", "suspended"):  # suspended can read; writes must be rejected later
                viewer = a
                org = o
                break
    if not viewer or not org:
        _log(endpoint, "error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Missing or invalid authentication context")

    # Writes rejected when org is suspended/deleted
    if org.get("status") != "active":
        _log(endpoint, "error", org_id=org.get("id"), meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Organization is not active")

    proj = next((p for p in planning if p.get("id") == project_id and p.get("entity_type") == "project" and p.get("status") != "deleted"), None)
    if not proj or proj.get("organization_id") != org.get("id"):
        _log(endpoint, "error", org_id=org.get("id"), meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Project not found")

    # Permission model not represented: ensure viewer belongs to org (already true) -> allow.

    # Enforce team_id if provided: must be a team in org and active
    if team_id is not None:
        t = next((x for x in accts if x.get("id") == team_id and x.get("entity_type") == "team" and x.get("organization_id") == org.get("id") and x.get("status") == "active"), None)
        if not t:
            _log(endpoint, "error", org_id=org.get("id"), meta={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Team not found")

    # Project constraints: entity_type=project => name not null. Ensure not setting to null/empty.
    # Also uniqueness on (org, entity_type, name) where not deleted.
    new_name = proj.get("name")
    if name is not None:
        new_name = name
        if new_name is None or new_name == "":
            _log(endpoint, "error", org_id=org.get("id"), meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Project name is required")
        clash = next((p for p in planning if p.get("entity_type") == "project" and p.get("organization_id") == org.get("id") and p.get("status") != "deleted" and p.get("name") == new_name and p.get("id") != project_id), None)
        if clash:
            _log(endpoint, "error", org_id=org.get("id"), meta={"code": "CONFLICT"})
            return _err("CONFLICT", "A project with that name already exists")

    # Lifecycle transition enforcement for status
    if status is not None:
        old = proj.get("status")
        transitions = {
            "planned": ["active", "canceled", "archived", "deleted"],
            "active": ["completed", "canceled", "archived", "deleted"],
            "completed": ["archived", "deleted"],
            "canceled": ["archived", "deleted"],
            "archived": ["deleted"],
            "deleted": [],
        }
        if old != status:
            allowed = transitions.get(old, [])
            if status not in allowed:
                _log(endpoint, "error", org_id=org.get("id"), meta={"code": "INVALID_TRANSITION"})
                return _err("INVALID_TRANSITION", f"Cannot transition project status from {old} to {status}")

    # Apply updates
    changed = False
    if name is not None and proj.get("name") != name:
        proj["name"] = name
        changed = True
    if description is not None and proj.get("description") != description:
        proj["description"] = description
        changed = True
    if status is not None and proj.get("status") != status:
        proj["status"] = status
        changed = True
    # planning schema doesn't include start_at/end_at for project, but tool exposes; accept and store as extra fields
    if start_iso is not None and proj.get("start_at") != start_iso:
        proj["start_at"] = start_iso
        changed = True
    if end_iso is not None and proj.get("end_at") != end_iso:
        proj["end_at"] = end_iso
        changed = True
    if team_id is not None and proj.get("team_id") != team_id:
        proj["team_id"] = team_id
        changed = True

    if not changed:
        # no success without effect
        _log(endpoint, "error", org_id=org.get("id"), meta={"code": "CONFLICT"})
        return _err("CONFLICT", "No changes to apply")

    proj["updated_at"] = _now()
    _save("planning.json", planning)
    _log(endpoint, "ok", org_id=org.get("id"), meta={"project_id": project_id})

    return {"project": proj}

def linear_addIssueToProject(project_id, issue_id, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_addIssueToProject"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status, organization_id=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "lin_req_" + uuid.uuid4().hex.upper(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "credential_id": None,
            "organization_id": organization_id,
        }
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(project_id, str) or re.match(r"^lin_plan_[0-9A-Z]{18,}$", project_id) is None:
        _log("error", message="project_id malformed")
        return _err("VALIDATION_ERROR", "project_id is malformed.")
    if not isinstance(issue_id, str) or re.match(r"^lin_iss_[0-9A-Z]{18,}$", issue_id) is None:
        _log("error", message="issue_id malformed")
        return _err("VALIDATION_ERROR", "issue_id is malformed.")

    planning = _load("planning.json")
    issues = _load("issues.json")
    activity = _load("issue_activity.json")
    if not isinstance(planning, list) or not isinstance(issues, list) or not isinstance(activity, list):
        _log("error", message="datastore corrupt")
        return _err("CONFLICT", "Datastore is in an unexpected format.")

    project = next((p for p in planning if isinstance(p, dict) and p.get("id") == project_id and p.get("entity_type") == "project" and p.get("status") != "deleted"), None)
    if project is None:
        _log("error", message="project not found")
        return _err("NOT_FOUND", "Project not found.")

    issue = next((i for i in issues if isinstance(i, dict) and i.get("id") == issue_id and i.get("status") != "deleted"), None)
    if issue is None:
        _log("error", organization_id=project.get("organization_id"), message="issue not found")
        return _err("NOT_FOUND", "Issue not found.")

    # same organization access
    if issue.get("organization_id") != project.get("organization_id"):
        _log("error", organization_id=project.get("organization_id"), message="cross-org association forbidden")
        return _err("NOT_FOUND", "Issue not found.")

    # Uniqueness: unique(entity_type, project_id, issue_id) where entity_type='project_issue' and status<>'deleted'
    existing = next((r for r in planning if isinstance(r, dict) and r.get("entity_type") == "project_issue" and r.get("status") != "deleted" and r.get("project_id") == project_id and r.get("issue_id") == issue_id), None)
    if existing is not None:
        _log("error", organization_id=project.get("organization_id"), message="already associated")
        return _err("CONFLICT", "Issue is already associated with the project.")

    now = _now_iso()
    assoc = {
        "id": "lin_plan_" + uuid.uuid4().hex.upper(),
        "organization_id": project.get("organization_id"),
        "entity_type": "project_issue",
        "status": "active",
        "team_id": None,
        "name": None,
        "description": None,
        "start_at": None,
        "end_at": None,
        "project_id": project_id,
        "cycle_id": None,
        "issue_id": issue_id,
        "created_at": now,
        "updated_at": now,
    }
    planning.append(assoc)

    # History event: added_to_project
    hist = {
        "id": "lin_act_" + uuid.uuid4().hex.upper(),
        "organization_id": issue.get("organization_id"),
        "entity_type": "issue_history_event",
        "status": "active",
        "issue_id": issue_id,
        "user_id": None,
        "body": None,
        "label_id": None,
        "related_issue_id": None,
        "relation_type": None,
        "event_type": "added_to_project",
        "event_payload": {"project_id": project_id},
        "source_issue_id": None,
        "duplicate_issue_id": None,
        "created_at": now,
        "updated_at": now,
    }
    activity.append(hist)

    # bump issue updated_at
    issue["updated_at"] = now

    _save("planning.json", planning)
    _save("issue_activity.json", activity)
    _save("issues.json", issues)
    _log("ok", organization_id=project.get("organization_id"))
    return {"association": assoc, "issue": issue}

def linear_getProjectIssues(project_id, limit=None, cursor=None, sort_by=None, sort_order=None, status=None, **_extra):
    import json, os, datetime, time, re, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_str, org_id=None, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"lin_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status_str,
            "organization_id": org_id,
            "credential_id": credential_id,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _decode_cursor(c):
        if c is None:
            return None, None
        if not isinstance(c, str) or c.strip() == "":
            return None, _err("VALIDATION_ERROR", "cursor is invalid")
        try:
            pad = "=" * ((4 - len(c) % 4) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "offset" not in obj:
                return None, _err("VALIDATION_ERROR", "cursor is not accepted")
            off = obj["offset"]
            if not isinstance(off, int) or off < 0:
                return None, _err("VALIDATION_ERROR", "cursor is not accepted")
            return obj, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is not accepted")

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    endpoint = "linear_getProjectIssues"

    if not isinstance(project_id, str) or not re.match(r"^lin_plan_[0-9A-Z]{18,}$", project_id):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "project_id is malformed")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

    allowed_sort_by = {"created_at", "updated_at", "priority", "number"}
    if sort_by is None:
        sort_by = "updated_at"
    if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort_by is invalid")

    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_order, str) or sort_order not in {"asc", "desc"}:
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort_order is invalid")

    if status is not None and (not isinstance(status, str) or status not in {"active", "archived", "deleted"}):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "status is invalid")

    cur, e = _decode_cursor(cursor)
    if e:
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return e
    offset = cur["offset"] if cur else 0

    orgs = _load("organizations.json")
    accts = _load("accounts.json")
    planning = _load("planning.json")
    issues = _load("issues.json")

    # Ambient auth context
    viewer = None
    org = None
    for a in accts:
        if a.get("entity_type") == "user" and a.get("is_viewer") is True and a.get("status") == "active":
            o = next((x for x in orgs if x.get("id") == a.get("organization_id")), None)
            if o and o.get("status") in ("active", "suspended"):
                viewer = a
                org = o
                break
    if not viewer or not org:
        _log(endpoint, "error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Missing or invalid authentication context")

    proj = next((p for p in planning if p.get("id") == project_id and p.get("entity_type") == "project" and p.get("status") != "deleted"), None)
    if not proj or proj.get("organization_id") != org.get("id"):
        _log(endpoint, "error", org_id=org.get("id"), meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Project not found")

    # Join through planning project_issue associations
    assoc_issue_ids = [
        p.get("issue_id") for p in planning
        if p.get("entity_type") == "project_issue"
        and p.get("project_id") == project_id
        and p.get("status") == "active"
    ]
    assoc_issue_ids = [x for x in assoc_issue_ids if isinstance(x, str)]
    issue_map = {i.get("id"): i for i in issues if isinstance(i, dict)}
    rows = []
    for iid in assoc_issue_ids:
        iss = issue_map.get(iid)
        if not iss:
            continue
        if iss.get("organization_id") != org.get("id"):
            continue
        if iss.get("status") == "deleted":
            continue
        if status is not None and iss.get("status") != status:
            continue
        rows.append(iss)

    total = len(rows)

    def _key(i):
        v = i.get(sort_by)
        if sort_by in ("created_at", "updated_at"):
            if isinstance(v, str):
                return v
            return ""
        if sort_by in ("priority", "number"):
            return v if isinstance(v, int) else 0
        return v

    reverse = (sort_order == "desc")
    rows.sort(key=_key, reverse=reverse)

    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor({"offset": next_off}) if has_more else None

    _log(endpoint, "ok", org_id=org.get("id"), meta={"project_id": project_id, "returned": len(page), "total": total})

    return {
        "nodes": page,
        "page_info": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "cursor": cursor,
        },
    }

