    cur, e = _decode_cursor(cursor)
    if e:
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return e
    offset = cur["offset"] if cur else 0

    orgs = _load("organizations.json")
    accts = _load("accounts.json")
    planning = _load("planning.json")

    # Validate organization exists
    org = next((o for o in orgs if o.get("id") == organization_id), None)
    if not org:
        _log(endpoint, "error", org_id=organization_id, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Organization not found")

    # Ambient auth: must have a viewer in the same org to access
    viewer = next((a for a in accts if a.get("entity_type") == "user" and a.get("is_viewer") is True and a.get("status") == "active" and a.get("organization_id") == organization_id), None)
    if not viewer:
        _log(endpoint, "error", org_id=organization_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Missing or invalid authentication context")

    # Validate team when provided
    if team_id is not None:
        team = next((a for a in accts if a.get("id") == team_id and a.get("entity_type") == "team" and a.get("organization_id") == organization_id and a.get("status") == "active"), None)
        if not team:
            _log(endpoint, "error", org_id=organization_id, meta={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Team not found")

    rows = []
    for p in planning:
        if not isinstance(p, dict):
            continue
        if p.get("entity_type") != "cycle":
            continue
        if p.get("organization_id") != organization_id:
            continue
        if p.get("status") == "deleted":
            continue
        if team_id is not None and p.get("team_id") != team_id:
            continue
        if status is not None and p.get("status") != status:
            continue
        rows.append(p)

    total = len(rows)

    def _key(r):
        v = r.get(sort_by)
        if sort_by in ("start_at", "end_at", "created_at", "updated_at"):
            return v if isinstance(v, str) else ""
        if sort_by == "name":
            return v if isinstance(v, str) else ""
        return v

    rows.sort(key=_key, reverse=(sort_order == "desc"))

    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor({"offset": next_off}) if has_more else None

    _log(endpoint, "ok", org_id=organization_id, meta={"returned": len(page), "total": total, "team_id": team_id, "status": status})

    return {
        "nodes": page,
        "page_info": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "cursor": cursor,
        },
    }

def linear_getActiveCycle(team_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
            else:
                dt = datetime.datetime.fromisoformat(s)
            return dt
        except ValueError:
            return None

    def _log(status_code, ok, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": f"lin_req_{int(time.time()*1000)}",
            "endpoint": "linear_getActiveCycle",
            "status": status_code,
            "ok": bool(ok),
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": now_iso
        }
        request_logs.append(entry)
        _save("request_logs.json", request_logs)

    # Basic rate limit: 120 requests per 60 seconds per endpoint (global, since no explicit credential context)
    window_s = 60
    limit = 120
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in request_logs:
        if r.get("endpoint") != "linear_getActiveCycle":
            continue
        ts = _parse_dt(r.get("timestamp"))
        if ts and ts >= cutoff:
            recent += 1
    if recent >= limit:
        _log(429, False, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    if not isinstance(team_id, str) or not re.match(r"^lin_acct_[0-9A-Z]{18,}$", team_id):
        _log(400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "team_id is malformed.")

    orgs = _load("organizations.json")
    accts = _load("accounts.json")
    planning = _load("planning.json")

    teams = [a for a in accts if a.get("id") == team_id and a.get("entity_type") == "team" and a.get("status") == "active"]
    if not teams:
        # team could exist but not active; still treat as not found/visible
        team_any = [a for a in accts if a.get("id") == team_id and a.get("entity_type") == "team" and a.get("status") != "deleted"]
        if not team_any:
            _log(404, False, "NOT_FOUND")
            return _err("NOT_FOUND", "Team not found.")
        _log(404, False, "NOT_FOUND")
        return _err("NOT_FOUND", "Team not found or not accessible.")
    team = teams[0]
    org_id = team.get("organization_id")

    # Ambient auth: require there exists an active viewer user for this org
    viewer = None
    for a in accts:
        if a.get("entity_type") == "user" and a.get("organization_id") == org_id and a.get("status") == "active" and a.get("is_viewer") is True:
            viewer = a
            break
    if viewer is None:
        _log(401, False, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated viewer context for this organization.")

    # org existence; reads can return suspended too, but if missing -> NOT_FOUND
    org = None
    for o in orgs:
        if o.get("id") == org_id and o.get("status") != "deleted":
            org = o
            break
    if org is None:
        _log(404, False, "NOT_FOUND")
        return _err("NOT_FOUND", "Organization not found.")

    # Active cycle: start_at <= now < end_at AND status='active'
    candidates = []
    for p in planning:
        if p.get("entity_type") != "cycle":
            continue
        if p.get("status") != "active":
            continue
        if p.get("organization_id") != org_id:
            continue
        if p.get("team_id") != team_id:
            continue
        sdt = _parse_dt(p.get("start_at"))
        edt = _parse_dt(p.get("end_at"))
        if not sdt or not edt:
            continue
        if sdt <= now and now < edt:
            candidates.append((sdt, p))

    if not candidates:
        _log(200, True)
        return {
            "data": None,
            "meta": {"team_id": team_id, "organization_id": org_id, "timestamp": now_iso}
        }

    # prefer latest start_at
    candidates.sort(key=lambda x: x[0], reverse=True)
    cycle = candidates[0][1]
    _log(200, True)
    return {
        "data": cycle,
        "meta": {"team_id": team_id, "organization_id": org_id, "timestamp": now_iso}
    }

def linear_getIssues(organization_id, team_id=None, assignee_id=None, state_id=None, status=None, priority=None, created_after=None, updated_after=None, search=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")
    def _load(n):
