            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []

    def _parse_dt(s, field_name):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an ISO 8601 date-time string.")
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]), None
            return datetime.datetime.fromisoformat(s), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be a valid ISO 8601 date-time.")

    def _log(status_code, ok, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": f"lin_req_{int(time.time()*1000)}",
            "endpoint": "linear_getIssues",
            "status": status_code,
            "ok": bool(ok),
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": now_iso
        }
        request_logs.append(entry)
        _save("request_logs.json", request_logs)

    # Rate limit: 240 reads per 60 seconds per endpoint (global)
    window_s = 60
    limit_rl = 240
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in request_logs:
        if r.get("endpoint") != "linear_getIssues":
            continue
        ts, _ = _parse_dt(r.get("timestamp"), "timestamp")
        if ts and ts >= cutoff:
            recent += 1
    if recent >= limit_rl:
        _log(429, False, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    if not isinstance(organization_id, str) or not re.match(r"^lin_org_[0-9A-Z]{18,}$", organization_id):
        _log(400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "organization_id is malformed.")

    def _validate_acct_id(val, name):
        if val is None:
            return None
        if not isinstance(val, str) or not re.match(r"^lin_acct_[0-9A-Z]{18,}$", val):
            return _err("VALIDATION_ERROR", f"{name} is malformed.")
        return None

    e = _validate_acct_id(team_id, "team_id") or _validate_acct_id(assignee_id, "assignee_id") or _validate_acct_id(state_id, "state_id")
    if e:
        _log(400, False, "VALIDATION_ERROR")
        return e

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log(400, False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status enum value.")
    if priority is not None:
        if not isinstance(priority, int) or priority not in (0, 1, 2, 3, 4):
            _log(400, False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid priority enum value.")

    created_after_dt, err = _parse_dt(created_after, "created_after")
    if err:
        _log(400, False, "VALIDATION_ERROR")
        return err
    updated_after_dt, err = _parse_dt(updated_after, "updated_after")
    if err:
        _log(400, False, "VALIDATION_ERROR")
        return err

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log(400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")

    if sort_by is None:
        sort_by = "updated_at"
    if sort_order is None:
        sort_order = "desc"
    if sort_by not in ("updated_at", "created_at", "priority", "number"):
        _log(400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort_by value.")
    if sort_order not in ("asc", "desc"):
        _log(400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort_order value.")

    # Cursor: base64 of "offset:<int>"
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            _log(400, False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                _log(400, False, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except Exception:
            _log(400, False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor cannot be used.")

    orgs = _load("organizations.json")
    accts = _load("accounts.json")
    issues = _load("issues.json")

    org = None
    for o in orgs:
        if o.get("id") == organization_id and o.get("status") != "deleted":
            org = o
            break
    if org is None:
        _log(404, False, "NOT_FOUND")
        return _err("NOT_FOUND", "Organization not found.")

    # Ambient auth: require viewer for org
    viewer = None
    for a in accts:
        if a.get("entity_type") == "user" and a.get("organization_id") == organization_id and a.get("status") == "active" and a.get("is_viewer") is True:
            viewer = a
            break
    if viewer is None:
        _log(401, False, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated viewer context for this organization.")

    # Validate referenced filters exist and are in org (team/user/state)
    if team_id is not None:
        ok = any(a.get("id") == team_id and a.get("entity_type") == "team" and a.get("organization_id") == organization_id and a.get("status") == "active" for a in accts)
        if not ok:
            _log(404, False, "NOT_FOUND")
            return _err("NOT_FOUND", "Team not found.")
    if assignee_id is not None:
        ok = any(a.get("id") == assignee_id and a.get("entity_type") == "user" and a.get("organization_id") == organization_id and a.get("status") == "active" for a in accts)
        if not ok:
            _log(404, False, "NOT_FOUND")
            return _err("NOT_FOUND", "Assignee not found.")
    if state_id is not None:
        # state visibility is via team; allow state even if archived? business says active workflow states for listing; use active
        ok = any(a.get("id") == state_id and a.get("entity_type") == "workflow_state" and a.get("organization_id") == organization_id and a.get("status") == "active" for a in accts)
        if not ok:
            _log(404, False, "NOT_FOUND")
            return _err("NOT_FOUND", "Workflow state not found.")

    # Filter
    q = []
    s_lower = search.lower() if isinstance(search, str) and search.strip() != "" else None

    for it in issues:
        if it.get("organization_id") != organization_id:
            continue
        if it.get("status") is None:
            continue
        # tool allows deleted filter; include if requested; otherwise default is active per business rule
        if status is None:
            if it.get("status") != "active":
                continue
        else:
            if it.get("status") != status:
                continue

        if team_id is not None and it.get("team_id") != team_id:
            continue
        if assignee_id is not None and it.get("assignee_id") != assignee_id:
            continue
        if state_id is not None and it.get("state_id") != state_id:
            continue
        if priority is not None and it.get("priority") != priority:
            continue

        if created_after_dt is not None:
            cdt, _ = _parse_dt(it.get("created_at"), "created_at")
            if not cdt or not (cdt > created_after_dt):
                continue
        if updated_after_dt is not None:
            udt, _ = _parse_dt(it.get("updated_at"), "updated_at")
            if not udt or not (udt > updated_after_dt):
                continue

        if s_lower:
            hay = " ".join([str(it.get("title") or ""), str(it.get("description") or ""), str(it.get("identifier") or "")]).lower()
            if s_lower not in hay:
                continue

        q.append(it)

    # Sort
    def _key(it):
        if sort_by in ("created_at", "updated_at"):
            dt, _ = _parse_dt(it.get(sort_by), sort_by)
            # None sorts last
            return dt or datetime.datetime.min
        return it.get(sort_by)

    reverse = (sort_order == "desc")
    try:
        q.sort(key=_key, reverse=reverse)
    except TypeError:
        # mixed None/int etc
        def _key2(it):
            v = it.get(sort_by)
            if v is None:
                return (1, None)
            return (0, v)
        q.sort(key=_key2, reverse=reverse)

    total = len(q)
    page = q[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    _log(200, True)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order,
            "timestamp": now_iso
        }
    }

