        if not isinstance(s, str):
            raise ValueError(f"{field} must be an RFC3339 datetime string")
        try:
            # Accept ...Z or offset
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            raise ValueError(f"{field} has invalid date-time format")

    def _log(status_code, used_org_id=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"lin_req_{int(time.time()*1000)}_{os.getpid()}",
            "service": "linear",
            "endpoint": "linear_searchIssues",
            "organization_id": used_org_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
        }
        if isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(organization_id, str) or not re.match(r"^lin_org_[0-9A-Z]{18,}$", organization_id):
        _log("VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "organization_id is malformed")

    def _check_id(val, pat, field):
        if val is None:
            return None
        if not isinstance(val, str) or not re.match(pat, val):
            raise ValueError(f"{field} is malformed")
        return val

    try:
        if query is not None and not isinstance(query, str):
            raise ValueError("query must be a string")
        _check_id(team_id, r"^lin_acct_[0-9A-Z]{18,}$", "team_id")
        _check_id(assignee_id, r"^lin_acct_[0-9A-Z]{18,}$", "assignee_id")
        _check_id(creator_id, r"^lin_acct_[0-9A-Z]{18,}$", "creator_id")
        _check_id(state_id, r"^lin_acct_[0-9A-Z]{18,}$", "state_id")
        _check_id(parent_issue_id, r"^lin_iss_[0-9A-Z]{18,}$", "parent_issue_id")

        if status is not None:
            if status not in ("active", "archived", "deleted"):
                raise ValueError("status must be one of: active, archived, deleted")
        if priority is not None:
            if not isinstance(priority, int) or priority not in (0, 1, 2, 3, 4):
                raise ValueError("priority must be one of: 0,1,2,3,4")
        if sort is not None and sort not in ("created_at", "updated_at", "priority", "number"):
            raise ValueError("sort must be one of: created_at, updated_at, priority, number")
        if order is not None and order not in ("asc", "desc"):
            raise ValueError("order must be one of: asc, desc")
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            raise ValueError("limit must be between 1 and 100")

        ca = _parse_dt(created_after, "created_after")
        cb = _parse_dt(created_before, "created_before")
        ua = _parse_dt(updated_after, "updated_after")
        ub = _parse_dt(updated_before, "updated_before")

        if ca and cb and cb < ca:
            raise ValueError("created_before must be >= created_after")
        if ua and ub and ub < ua:
            raise ValueError("updated_before must be >= updated_after")
    except ValueError as e:
        _log("VALIDATION_ERROR", organization_id)
        return _err("VALIDATION_ERROR", str(e))

    # Resolve org context; reads allowed even if suspended, but org must exist
    orgs = _load("organizations.json")
    org = next((o for o in orgs if o.get("id") == organization_id and o.get("status") != "deleted"), None)
    if not org:
        _log("NOT_FOUND", organization_id)
        return _err("NOT_FOUND", "Organization not found")

    # Cursor decode (opaque)
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            _log("VALIDATION_ERROR", organization_id)
            return _err("VALIDATION_ERROR", "cursor is malformed")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or payload.get("org") != organization_id or "offset" not in payload:
                raise ValueError("unrecognized cursor")
            offset = payload["offset"]
            if not isinstance(offset, int) or offset < 0:
                raise ValueError("unrecognized cursor")
        except Exception:
            _log("VALIDATION_ERROR", organization_id)
            return _err("VALIDATION_ERROR", "Unrecognized cursor")

    issues = _load("issues.json")

    # Filter (must not return deleted)
    def _dt_from_row(v):
        if not v or not isinstance(v, str):
            return None
        try:
            if v.endswith("Z"):
                return datetime.datetime.fromisoformat(v[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    ca = _parse_dt(created_after, "created_after") if created_after else None
    cb = _parse_dt(created_before, "created_before") if created_before else None
    ua = _parse_dt(updated_after, "updated_after") if updated_after else None
    ub = _parse_dt(updated_before, "updated_before") if updated_before else None

    q = (query or "").strip().lower()
    out = []
    for it in issues:
        if it.get("organization_id") != organization_id:
            continue
        if it.get("status") == "deleted":
            continue
        if status is not None and it.get("status") != status:
            continue
        if team_id is not None and it.get("team_id") != team_id:
            continue
        if assignee_id is not None and it.get("assignee_id") != assignee_id:
            continue
        if creator_id is not None and it.get("creator_id") != creator_id:
            continue
        if state_id is not None and it.get("state_id") != state_id:
            continue
        if priority is not None and it.get("priority") != priority:
            continue
        if parent_issue_id is not None and it.get("parent_issue_id") != parent_issue_id:
            continue

        cdt = _dt_from_row(it.get("created_at"))
        udt = _dt_from_row(it.get("updated_at"))
        if ca and (cdt is None or cdt < ca):
            continue
        if cb and (cdt is None or cdt > cb):
            continue
        if ua and (udt is None or udt < ua):
            continue
        if ub and (udt is None or udt > ub):
            continue

        if q:
            hay = " ".join([
                str(it.get("identifier") or ""),
                str(it.get("title") or ""),
                str(it.get("description") or ""),
            ]).lower()
            if q not in hay:
                continue

        out.append(it)

    # Sorting
    if sort is None:
        sort = "updated_at"
    if order is None:
        order = "desc"

    reverse = (order == "desc")

    def _sort_key(row):
        if sort in ("created_at", "updated_at"):
            dt = _dt_from_row(row.get(sort))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return row.get(sort)

    try:
        out.sort(key=_sort_key, reverse=reverse)
    except Exception:
        # If heterogeneous types or missing values break sort, return validation error-like behavior
        _log("VALIDATION_ERROR", organization_id)
        return _err("VALIDATION_ERROR", "Unable to sort with the provided sort field")

    total = len(out)
    page = out[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {"v": 1, "org": organization_id, "offset": next_offset}
        enc = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    _log("OK", organization_id)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "offset": offset,
        },
    }

def linear_createIssue(organization_id, team_id, title, description=None, priority=None, estimate=None, state_id=None, assignee_id=None, parent_issue_id=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _log(status_code, used_org_id=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"lin_req_{int(time.time()*1000)}_{os.getpid()}",
            "service": "linear",
            "endpoint": "linear_createIssue",
            "organization_id": used_org_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
        }
        if isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)

    # Validate
    if not isinstance(organization_id, str) or not re.match(r"^lin_org_[0-9A-Z]{18,}$", organization_id):
        _log("VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "organization_id is malformed")
    if not isinstance(team_id, str) or not re.match(r"^lin_acct_[0-9A-Z]{18,}$", team_id):
        _log("VALIDATION_ERROR", organization_id)
        return _err("VALIDATION_ERROR", "team_id is malformed")
    if not isinstance(title, str) or title.strip() == "":
        _log("VALIDATION_ERROR", organization_id)
        return _err("VALIDATION_ERROR", "title is required")

    if description is not None and not isinstance(description, str):
        _log("VALIDATION_ERROR", organization_id)
        return _err("VALIDATION_ERROR", "description must be a string")
    if priority is None:
        priority = 3
    if not isinstance(priority, int) or priority not in (0, 1, 2, 3, 4):
        _log("VALIDATION_ERROR", organization_id)
        return _err("VALIDATION_ERROR", "priority must be one of: 0,1,2,3,4")
    if estimate is not None:
        if not isinstance(estimate, (int, float)):
            _log("VALIDATION_ERROR", organization_id)
            return _err("VALIDATION_ERROR", "estimate must be a number")
        if estimate < 0 or estimate > 1000:
            _log("VALIDATION_ERROR", organization_id)
            return _err("VALIDATION_ERROR", "estimate must be between 0 and 1000")
        estimate = float(estimate)

    if state_id is not None and (not isinstance(state_id, str) or not re.match(r"^lin_acct_[0-9A-Z]{18,}$", state_id)):
        _log("VALIDATION_ERROR", organization_id)
        return _err("VALIDATION_ERROR", "state_id is malformed")
    if assignee_id is not None and (not isinstance(assignee_id, str) or not re.match(r"^lin_acct_[0-9A-Z]{18,}$", assignee_id)):
        _log("VALIDATION_ERROR", organization_id)
        return _err("VALIDATION_ERROR", "assignee_id is malformed")
    if parent_issue_id is not None and (not isinstance(parent_issue_id, str) or not re.match(r"^lin_iss_[0-9A-Z]{18,}$", parent_issue_id)):
        _log("VALIDATION_ERROR", organization_id)
        return _err("VALIDATION_ERROR", "parent_issue_id is malformed")

    orgs = _load("organizations.json")
    org = next((o for o in orgs if o.get("id") == organization_id), None)
    if not org or org.get("status") == "deleted":
        _log("NOT_FOUND", organization_id)
        return _err("NOT_FOUND", "Organization not found")
    if org.get("status") != "active":
        _log("UNAUTHORIZED", organization_id)
        return _err("UNAUTHORIZED", "Organization is not active")

    accounts = _load("accounts.json")

    team = next((a for a in accounts if a.get("id") == team_id and a.get("organization_id") == organization_id and a.get("entity_type") == "team" and a.get("status") == "active"), None)
    if not team:
        _log("VALIDATION_ERROR", organization_id)
        return _err("VALIDATION_ERROR", "team_id does not reference an active team in the organization")

    # Resolve viewer (ambient auth)
    viewer = next((a for a in accounts if a.get("organization_id") == organization_id and a.get("entity_type") == "user" and a.get("status") == "active" and a.get("is_viewer") is True), None)
    if not viewer:
        _log("UNAUTHORIZED", organization_id)
        return _err("UNAUTHORIZED", "No authenticated viewer in organization context")

    creator_id = viewer.get("id")

    # State validation: required by business rules; if not provided, pick first active workflow_state in team by position
    states = [a for a in accounts if a.get("organization_id") == organization_id and a.get("entity_type") == "workflow_state" and a.get("status") == "active" and a.get("team_id") == team_id]
    if state_id is None:
        if not states:
            _log("VALIDATION_ERROR", organization_id)
            return _err("VALIDATION_ERROR", "state_id is required and no default workflow state exists for team")
        states.sort(key=lambda s: (s.get("position") if isinstance(s.get("position"), int) else 10**9))
        state_id = states[0].get("id")
    else:
        st = next((s for s in states if s.get("id") == state_id), None)
        if not st:
            _log("VALIDATION_ERROR", organization_id)
            return _err("VALIDATION_ERROR", "state_id must reference an active workflow_state in the same team")

    # Assignee validation
    if assignee_id is not None:
        ass = next((a for a in accounts if a.get("id") == assignee_id and a.get("organization_id") == organization_id and a.get("entity_type") == "user" and a.get("status") == "active"), None)
        if not ass:
            _log("VALIDATION_ERROR", organization_id)
            return _err("VALIDATION_ERROR", "assignee_id must reference an active user in the organization")

    issues = _load("issues.json")
    now = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    # Parent validation (same org, not self; ensure no cycles)
    if parent_issue_id is not None:
        parent = next((i for i in issues if i.get("id") == parent_issue_id and i.get("organization_id") == organization_id and i.get("status") != "deleted"), None)
        if not parent:
            _log("VALIDATION_ERROR", organization_id)
            return _err("VALIDATION_ERROR", "parent_issue_id must reference an existing issue in the organization")

    # Allocate next number per team_id (best-effort atomic within single-process file store)
    existing_numbers = [i.get("number") for i in issues if i.get("team_id") == team_id and i.get("status") != "deleted" and isinstance(i.get("number"), int)]
    next_number = (max(existing_numbers) + 1) if existing_numbers else 1
    if next_number <= 0:
        next_number = 1

    team_key = team.get("key")
    if not isinstance(team_key, str) or team_key.strip() == "":
        _log("VALIDATION_ERROR", organization_id)
        return _err("VALIDATION_ERROR", "Team key is missing; cannot generate identifier")
    identifier = f"{team_key}-{next_number}"

    # Enforce uniqueness (team_id, number) and (team_id, identifier)
    if any(i for i in issues if i.get("team_id") == team_id and i.get("status") != "deleted" and i.get("number") == next_number):
        _log("CONFLICT", organization_id)
        return _err("CONFLICT", "Issue number conflict; please retry")
    if any(i for i in issues if i.get("team_id") == team_id and i.get("status") != "deleted" and i.get("identifier") == identifier):
        _log("CONFLICT", organization_id)
        return _err("CONFLICT", "Issue identifier conflict; please retry")

    # Create ID
    def _gen_id(prefix):
        # 18 chars base36-ish uppercase
        import random, string
        alphabet = string.ascii_uppercase + string.digits
        return prefix + "".join(random.choice(alphabet) for _ in range(18))

    new_id = _gen_id("lin_iss_")
    while any(i for i in issues if i.get("id") == new_id):
        new_id = _gen_id("lin_iss_")

    row = {
        "id": new_id,
        "organization_id": organization_id,
        "team_id": team_id,
        "number": next_number,
        "identifier": identifier,
        "title": title,
        "description": description,
        "priority": priority,
        "estimate": estimate,
        "state_id": state_id,
        "assignee_id": assignee_id,
        "creator_id": creator_id,
        "parent_issue_id": parent_issue_id,
        "archived_at": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    issues.append(row)
    _save("issues.json", issues)

    # Write issue_history_event "created"
    activity = _load("issue_activity.json")

    def _gen_act_id():
        import random, string
        alphabet = string.ascii_uppercase + string.digits
        return "lin_act_" + "".join(random.choice(alphabet) for _ in range(18))

    act_id = _gen_act_id()
    while any(a for a in activity if a.get("id") == act_id):
        act_id = _gen_act_id()

    activity.append({
        "id": act_id,
        "organization_id": organization_id,
        "entity_type": "issue_history_event",
        "status": "active",
        "issue_id": new_id,
        "user_id": creator_id,
        "body": None,
        "label_id": None,
        "related_issue_id": None,
        "relation_type": None,
        "event_type": "created",
        "event_payload": {
            "identifier": identifier,
            "team_id": team_id,
            "state_id": state_id,
        },
        "source_issue_id": None,
        "duplicate_issue_id": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("issue_activity.json", activity)

    _log("OK", organization_id)
    return {"data": row}

def linear_updateIssue(issue_id, title=None, description=None, priority=None, estimate=None, state_id=None, assignee_id=None, parent_issue_id=None, status=None, archived_at=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_updateIssue"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_s, organization_id=None, credential_id=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "lin_req_" + uuid.uuid4().hex.upper(),
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "credential_id": credential_id,
            "organization_id": organization_id,
        }
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt_or_null(v, field):
        if v is None:
            return None, None, True
        if not isinstance(v, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string or null."), False
        try:
            ss = v[:-1] + "+00:00" if v.endswith("Z") else v
            dt = datetime.datetime.fromisoformat(ss)
            return dt, None, False
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string or null."), False

    try:
        if not isinstance(issue_id, str) or re.match(r"^lin_iss_[0-9A-Z]{18,}$", issue_id) is None:
            _log("error", message="issue_id malformed")
            return _err("VALIDATION_ERROR", "issue_id is malformed")
        if title is not None and (not isinstance(title, str) or title.strip() == ""):
            _log("error", message="title invalid")
            return _err("VALIDATION_ERROR", "title must be a non-empty string")
        if description is not None and not isinstance(description, str):
            _log("error", message="description invalid")
            return _err("VALIDATION_ERROR", "description must be a string")
        if priority is not None and (not isinstance(priority, int) or priority not in (0, 1, 2, 3, 4)):
            _log("error", message="priority invalid")
            return _err("VALIDATION_ERROR", "priority must be one of: 0,1,2,3,4")
        if estimate is not None:
            if not isinstance(estimate, (int, float)) or estimate < 0 or estimate > 1000:
                _log("error", message="estimate invalid")
                return _err("VALIDATION_ERROR", "estimate must be a number between 0 and 1000")
        if state_id is not None:
            if not isinstance(state_id, str) or re.match(r"^lin_acct_[0-9A-Z]{18,}$", state_id) is None:
                _log("error", message="state_id malformed")
                return _err("VALIDATION_ERROR", "state_id is malformed")
        if assignee_id is not None:
            if not isinstance(assignee_id, str) or re.match(r"^lin_acct_[0-9A-Z]{18,}$", assignee_id) is None:
                _log("error", message="assignee_id malformed")
                return _err("VALIDATION_ERROR", "assignee_id is malformed")
        if parent_issue_id is not None:
            if not isinstance(parent_issue_id, str) or re.match(r"^lin_iss_[0-9A-Z]{18,}$", parent_issue_id) is None:
                _log("error", message="parent_issue_id malformed")
                return _err("VALIDATION_ERROR", "parent_issue_id is malformed")
        if status is not None:
            if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
                _log("error", message="status invalid")
                return _err("VALIDATION_ERROR", "status is invalid")
        if archived_at is not None and not isinstance(archived_at, str):
            _log("error", message="archived_at invalid")
            return _err("VALIDATION_ERROR", "archived_at must be an RFC3339 date-time string or null")
    except Exception:
        _log("error", message="validation crash")
        return _err("CONFLICT", "Unexpected validation failure.")

    orgs = _load("organizations.json")
    accts = _load("accounts.json")
    issues = _load("issues.json")
    activity = _load("issue_activity.json")
    if not isinstance(orgs, list) or not isinstance(accts, list) or not isinstance(issues, list) or not isinstance(activity, list):
        _log("error", message="datastore corrupt")
        return _err("CONFLICT", "Datastore is in an unexpected format.")

    issue = next((i for i in issues if isinstance(i, dict) and i.get("id") == issue_id and i.get("status") != "deleted"), None)
    if not issue:
        _log("error", message="issue not found")
        return _err("NOT_FOUND", "Issue not found.")

    org_id = issue.get("organization_id")
    org = next((o for o in orgs if isinstance(o, dict) and o.get("id") == org_id), None)
    if not org:
        _log("error", organization_id=org_id, message="org not found")
        return _err("NOT_FOUND", "Organization not found.")

    if org.get("status") != "active":
        _log("error", organization_id=org_id, message="org not active")
        return _err("UNAUTHORIZED", "Organization is not active.")

    # Viewer context: for operations that need actor, pick org viewer; do not fail if missing if not needed,
    # but history events should have user_id when possible.
    viewer = next((a for a in accts if isinstance(a, dict) and a.get("entity_type") == "user" and a.get("organization_id") == org_id and a.get("status") == "active" and a.get("is_viewer") is True), None)

    # Prepare changes + validate references
    changes = {}
    if title is not None and title != issue.get("title"):
        changes["title"] = title
    if description is not None and description != issue.get("description"):
        changes["description"] = description
    if priority is not None and priority != issue.get("priority"):
        changes["priority"] = priority
    if estimate is not None and estimate != issue.get("estimate"):
        changes["estimate"] = float(estimate) if isinstance(estimate, (int, float)) else estimate

    team_id = issue.get("team_id")

    if state_id is not None and state_id != issue.get("state_id"):
        st = next((a for a in accts if isinstance(a, dict) and a.get("id") == state_id and a.get("entity_type") == "workflow_state" and a.get("team_id") == team_id and a.get("status") == "active"), None)
        if not st:
            _log("error", organization_id=org_id, message="invalid state for team")
            return _err("NOT_FOUND", "Workflow state not found for this team.")
        changes["state_id"] = state_id

    if assignee_id is not None and assignee_id != issue.get("assignee_id"):
        ass = next((a for a in accts if isinstance(a, dict) and a.get("id") == assignee_id and a.get("entity_type") == "user" and a.get("organization_id") == org_id and a.get("status") == "active"), None)
        if not ass:
            _log("error", organization_id=org_id, message="assignee not found")
            return _err("NOT_FOUND", "Assignee not found.")
        changes["assignee_id"] = assignee_id

    if parent_issue_id is not None and parent_issue_id != issue.get("parent_issue_id"):
        if parent_issue_id == issue_id:
            _log("error", organization_id=org_id, message="parent is self")
            return _err("VALIDATION_ERROR", "parent_issue_id cannot equal issue_id.")
        parent = next((i for i in issues if isinstance(i, dict) and i.get("id") == parent_issue_id and i.get("status") != "deleted"), None)
        if not parent or parent.get("organization_id") != org_id:
            _log("error", organization_id=org_id, message="parent not found")
            return _err("NOT_FOUND", "Parent issue not found.")
        # prevent cycles: walk up parent chain
        seen = {issue_id}
        cur = parent
        while cur and cur.get("parent_issue_id"):
            pid = cur.get("parent_issue_id")
            if pid in seen:
                _log("error", organization_id=org_id, message="cycle detected")
                return _err("CONFLICT", "parent_issue_id would create a cycle.")
            seen.add(pid)
            cur = next((i for i in issues if isinstance(i, dict) and i.get("id") == pid and i.get("status") != "deleted"), None)
            if cur and cur.get("organization_id") != org_id:
                cur = None
        changes["parent_issue_id"] = parent_issue_id

    # Status / archive semantics
    if status is not None and status != issue.get("status"):
        transitions = {
            "active": {"archived", "deleted"},
            "archived": {"active", "deleted"},
            "deleted": set(),
        }
        cur = issue.get("status")
        if status not in transitions.get(cur, set()):
            _log("error", organization_id=org_id, message="invalid transition")
            return _err("INVALID_TRANSITION", f"Cannot transition issue status from '{cur}' to '{status}'.")
        changes["status"] = status
        if status == "archived":
            changes["archived_at"] = _now_iso()
        elif status == "active":
            changes["archived_at"] = None

    # archived_at override (only meaningful if status archived/active)
    if archived_at is not None:
        dt, err, was_null = _parse_dt_or_null(archived_at, "archived_at")
        if err:
            _log("error", organization_id=org_id, message="archived_at invalid")
            return err
        # If provided, apply directly (allow null to clear). This matches tool params.
        changes["archived_at"] = None if was_null else archived_at

    if not changes:
        _log("ok", organization_id=org_id, message="no changes")
        return {"issue": issue, "updated": False}

    now = _now_iso()

    # Apply changes and write history events
    for field, new_val in changes.items():
        old_val = issue.get(field)
        issue[field] = new_val
        event_type = "updated"
        if field == "state_id":
            event_type = "state_changed"
        elif field == "priority":
            event_type = "priority_changed"
        elif field == "assignee_id":
            event_type = "assignee_changed"
        elif field == "status":
            if new_val == "archived":
                event_type = "archived"
            elif new_val == "active" and old_val == "archived":
                event_type = "unarchived"
            else:
                event_type = "updated"

        hist = {
            "id": "lin_act_" + uuid.uuid4().hex.upper(),
            "organization_id": org_id,
            "entity_type": "issue_history_event",
            "status": "active",
            "issue_id": issue_id,
            "user_id": viewer.get("id") if viewer else None,
            "body": None,
            "label_id": None,
            "related_issue_id": None,
            "relation_type": None,
            "event_type": event_type,
            "event_payload": {"field": field, "before": old_val, "after": new_val},
            "source_issue_id": None,
            "duplicate_issue_id": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(hist)

    issue["updated_at"] = now
    _save("issues.json", issues)
    _save("issue_activity.json", activity)

    _log("ok", organization_id=org_id)
    return {"issue": issue, "updated": True}

def linear_createComment(issue_id, user_id, body, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _log(status_code, used_org_id=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"lin_req_{int(time.time()*1000)}_{os.getpid()}",
            "service": "linear",
            "endpoint": "linear_createComment",
            "organization_id": used_org_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
        }
        if isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)

    if not isinstance(issue_id, str) or not re.match(r"^lin_iss_[0-9A-Z]{18,}$", issue_id):
        _log("VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "issue_id is malformed")
    if not isinstance(user_id, str) or not re.match(r"^lin_acct_[0-9A-Z]{18,}$", user_id):
        _log("VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "user_id is malformed")
    if not isinstance(body, str) or body.strip() == "":
        _log("VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "body is required")

    issues = _load("issues.json")
    issue_idx = next((i for i, it in enumerate(issues) if it.get("id") == issue_id), None)
    if issue_idx is None:
        _log("NOT_FOUND", None)
        return _err("NOT_FOUND", "Issue not found")
    issue = issues[issue_idx]
    org_id = issue.get("organization_id")

    # Org must be active for writes
    orgs = _load("organizations.json")
    org = next((o for o in orgs if o.get("id") == org_id), None)
    if not org or org.get("status") == "deleted":
        _log("NOT_FOUND", org_id)
        return _err("NOT_FOUND", "Organization not found")
    if org.get("status") != "active":
        _log("UNAUTHORIZED", org_id)
        return _err("UNAUTHORIZED", "Organization is not active")

    accounts = _load("accounts.json")
    viewer = next((a for a in accounts if a.get("organization_id") == org_id and a.get("entity_type") == "user" and a.get("status") == "active" and a.get("is_viewer") is True), None)
    if not viewer:
        _log("UNAUTHORIZED", org_id)
        return _err("UNAUTHORIZED", "No authenticated viewer in organization context")

    # Enforce user_id=viewer (tool provides user_id, but business rule sets comment user to viewer)
    if user_id != viewer.get("id"):
        _log("UNAUTHORIZED", org_id)
        return _err("UNAUTHORIZED", "user_id must match the authenticated viewer")

    # Cannot comment on deleted issue (archived allowed)
    if issue.get("status") == "deleted":
        _log("INVALID_TRANSITION", org_id)
        return _err("INVALID_TRANSITION", "Cannot comment on a deleted issue")

    activity = _load("issue_activity.json")
    now = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_act_id():
        import random, string
        alphabet = string.ascii_uppercase + string.digits
        return "lin_act_" + "".join(random.choice(alphabet) for _ in range(18))

    # Insert comment
    comment_id = _gen_act_id()
    while any(a for a in activity if a.get("id") == comment_id):
        comment_id = _gen_act_id()

    comment = {
        "id": comment_id,
        "organization_id": org_id,
        "entity_type": "comment",
        "status": "active",
        "issue_id": issue_id,
        "user_id": viewer.get("id"),
        "body": body,
        "label_id": None,
        "related_issue_id": None,
        "relation_type": None,
        "event_type": None,
        "event_payload": None,
        "source_issue_id": None,
        "duplicate_issue_id": None,
        "created_at": now,
        "updated_at": now,
    }
    activity.append(comment)

    # Insert issue_history_event(event_type='updated') (not 'created' for first comment)
    evt_id = _gen_act_id()
    while any(a for a in activity if a.get("id") == evt_id):
        evt_id = _gen_act_id()

    activity.append({
        "id": evt_id,
        "organization_id": org_id,
        "entity_type": "issue_history_event",
        "status": "active",
        "issue_id": issue_id,
        "user_id": viewer.get("id"),
        "body": None,
        "label_id": None,
        "related_issue_id": None,
        "relation_type": None,
        "event_type": "updated",
        "event_payload": {"comment_id": comment_id},
        "source_issue_id": None,
        "duplicate_issue_id": None,
        "created_at": now,
        "updated_at": now,
    })

    _save("issue_activity.json", activity)

    # bump issue updated_at
    issue["updated_at"] = now
    issues[issue_idx] = issue
    _save("issues.json", issues)

    _log("OK", org_id)
    return {"data": comment}

