    before = issue.get("assignee_id")
    if before == assignee_id:
        # idempotent success, but still log a history event? Real APIs often treat as no-op; avoid mutation without effect.
        _log("ok", organization_id=org_id)
        return {"issue": issue}

    now = _now_iso()
    issue["assignee_id"] = assignee_id
    issue["updated_at"] = now

