        "created_at": now,
        "updated_at": now,
    }
    activity.append(hist)

    _save("issues.json", issues)
    _save("issue_activity.json", activity)
    _log("ok", organization_id=org_id)
    return {"issue": issue}

def linear_subscribeToIssue(issue_id, user_id, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_subscribeToIssue"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, organization_id=None, message=None):
        logs = _load("request_logs.json")
        row = {
            "id": "lin_req_" + uuid.uuid4().hex.upper(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": credential_id,
            "organization_id": organization_id,
        }
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(issue_id, str) or not re.match(r"^lin_iss_[0-9A-Z]{18,}$", issue_id):
            _log("error", message="validation issue_id")
            return _err("VALIDATION_ERROR", "Malformed issue_id.")
        if not isinstance(user_id, str) or not re.match(r"^lin_acct_[0-9A-Z]{18,}$", user_id):
            _log("error", message="validation user_id")
            return _err("VALIDATION_ERROR", "Malformed user_id.")

        orgs = _load("organizations.json")
        accts = _load("accounts.json")
        issues = _load("issues.json")
        activity = _load("issue_activity.json")

        issue = next((x for x in issues if x.get("id") == issue_id), None)
        if not issue or issue.get("status") == "deleted":
            _log("error", message="issue not found")
            return _err("NOT_FOUND", "Issue not found.")

        org_id = issue.get("organization_id")
        org = next((o for o in orgs if o.get("id") == org_id), None)
        if not org:
            _log("error", organization_id=org_id, message="org not found")
            return _err("NOT_FOUND", "Organization not found.")
        if org.get("status") != "active":
            _log("error", organization_id=org_id, message="org not active")
            return _err("UNAUTHORIZED", "Organization is not active for write operations.")

        user = next((a for a in accts if a.get("id") == user_id and a.get("entity_type") == "user" and a.get("status") == "active"), None)
        if not user or user.get("organization_id") != org_id:
            _log("error", organization_id=org_id, message="user not found/in org")
            return _err("NOT_FOUND", "User not found or not accessible in the workspace.")

        existing = next((r for r in activity
                         if r.get("entity_type") == "issue_subscription"
                         and r.get("status") == "active"
                         and r.get("issue_id") == issue_id
                         and r.get("user_id") == user_id), None)
        if existing:
            _log("error", organization_id=org_id, message="already subscribed")
            return _err("CONFLICT", "User is already subscribed to this issue.")

        now = _now()
        sub = {
            "id": "lin_act_" + uuid.uuid4().hex.upper(),
            "organization_id": org_id,
            "entity_type": "issue_subscription",
            "status": "active",
            "issue_id": issue_id,
            "user_id": user_id,
            "body": None,
            "label_id": None,
            "related_issue_id": None,
            "relation_type": None,
            "event_type": None,
            "event_payload": None,
            "source_issue_id": None,
            "duplicate_issue_id": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(sub)

        _save("issue_activity.json", activity)

        subscribers_active = [r.get("user_id") for r in activity
                              if r.get("entity_type") == "issue_subscription" and r.get("status") == "active" and r.get("issue_id") == issue_id]

        _log("ok", organization_id=org_id)
        return {"issue_id": issue_id, "subscriber_ids": subscribers_active}
    except Exception as e:
        try:
            _log("error", message="internal error: " + str(e))
        except Exception:
            pass
        return _err("CONFLICT", "Internal error.")

