                {
                    "id": _gen_id("lin_req_"),
                    "endpoint": "linear_archiveIssue",
                    "status": "error",
                    "error_code": err["error"]["code"],
                    "ts": _now(),
                    "latency_ms": int((time.time() - t0) * 1000),
                }
            )
            _save("request_log.json", logs)
        except Exception:
            pass
        return err

    orgs = _load("organizations.json")
    accounts = _load("accounts.json")
    issues = _load("issues.json")
    activity = _load("issue_activity.json")

    # Resolve auth context for writes (org active + viewer)
    viewer = None
    org = None
    for o in orgs:
        if o.get("status") == "active":
            for a in accounts:
                if (
                    a.get("organization_id") == o.get("id")
                    and a.get("entity_type") == "user"
                    and a.get("status") == "active"
                    and a.get("is_viewer") is True
                ):
                    org = o
                    viewer = a
                    break
        if viewer:
            break
    if not viewer or not org:
        err = _err("UNAUTHORIZED", "No authenticated workspace context is available for this operation.")
        try:
            logs = _load("request_log.json")
            logs.append(
                {
                    "id": _gen_id("lin_req_"),
                    "endpoint": "linear_archiveIssue",
                    "status": "error",
                    "error_code": err["error"]["code"],
                    "ts": _now(),
                    "latency_ms": int((time.time() - t0) * 1000),
                }
            )
            _save("request_log.json", logs)
        except Exception:
            pass
        return err

    # Find issue
    issue_row = None
    for r in issues:
        if r.get("id") == issue_id and r.get("organization_id") == org.get("id") and r.get("status") != "deleted":
            issue_row = r
            break
    if not issue_row:
        err = _err("NOT_FOUND", "Issue not found.")
        try:
            logs = _load("request_log.json")
            logs.append(
                {
                    "id": _gen_id("lin_req_"),
                    "endpoint": "linear_archiveIssue",
                    "organization_id": org.get("id"),
                    "viewer_id": viewer.get("id"),
                    "status": "error",
                    "error_code": err["error"]["code"],
                    "ts": _now(),
                    "latency_ms": int((time.time() - t0) * 1000),
                }
            )
            _save("request_log.json", logs)
        except Exception:
            pass
        return err

    # Lifecycle transition enforcement
    if issue_row.get("status") == "archived":
        err = _err("CONFLICT", "Issue is already archived.")
        try:
            logs = _load("request_log.json")
            logs.append(
                {
                    "id": _gen_id("lin_req_"),
                    "endpoint": "linear_archiveIssue",
                    "organization_id": org.get("id"),
                    "viewer_id": viewer.get("id"),
                    "status": "error",
                    "error_code": err["error"]["code"],
                    "ts": _now(),
                    "latency_ms": int((time.time() - t0) * 1000),
                }
            )
            _save("request_log.json", logs)
        except Exception:
            pass
        return err
    if issue_row.get("status") not in ["active", "archived", "deleted"]:
        err = _err("INVALID_TRANSITION", "Issue status is invalid.")
        try:
            logs = _load("request_log.json")
            logs.append(
                {
                    "id": _gen_id("lin_req_"),
                    "endpoint": "linear_archiveIssue",
                    "organization_id": org.get("id"),
                    "viewer_id": viewer.get("id"),
                    "status": "error",
                    "error_code": err["error"]["code"],
                    "ts": _now(),
                    "latency_ms": int((time.time() - t0) * 1000),
                }
            )
            _save("request_log.json", logs)
        except Exception:
            pass
        return err
    if issue_row.get("status") == "deleted":
        err = _err("INVALID_TRANSITION", "Cannot archive a deleted issue.")
        try:
            logs = _load("request_log.json")
            logs.append(
                {
                    "id": _gen_id("lin_req_"),
                    "endpoint": "linear_archiveIssue",
                    "organization_id": org.get("id"),
                    "viewer_id": viewer.get("id"),
                    "status": "error",
                    "error_code": err["error"]["code"],
                    "ts": _now(),
                    "latency_ms": int((time.time() - t0) * 1000),
                }
            )
            _save("request_log.json", logs)
        except Exception:
            pass
        return err

    now = _now()
    before_status = issue_row.get("status")
    issue_row["status"] = "archived"
    issue_row["archived_at"] = now
    issue_row["updated_at"] = now

    # history event
    activity.append(
        {
            "id": _gen_id("lin_act_"),
            "organization_id": org.get("id"),
            "entity_type": "issue_history_event",
            "status": "active",
            "issue_id": issue_id,
            "user_id": viewer.get("id"),
            "event_type": "archived",
            "event_payload": {"status": {"before": before_status, "after": "archived"}},
            "created_at": now,
            "updated_at": now,
        }
    )

    _save("issues.json", issues)
    _save("issue_activity.json", activity)

    # log
    try:
        logs = _load("request_log.json")
        logs.append(
            {
                "id": _gen_id("lin_req_"),
                "endpoint": "linear_archiveIssue",
                "organization_id": org.get("id"),
                "viewer_id": viewer.get("id"),
                "status": "ok",
                "ts": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("request_log.json", logs)
    except Exception:
        pass

    return {"issue": issue_row}

