def linear_transferIssue(issue_id, team_id, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b64e(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _log(endpoint, status, credential_id=None, organization_id=None, meta=None, started=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        ended = time.time()
        latency_ms = None
        if started is not None:
            latency_ms = int(round((ended - started) * 1000))
        logs.append({
            "id": f"lin_req_{int(ended*1000)}",
            "endpoint": endpoint,
            "status": status,
            "credential_id": credential_id,
            "organization_id": organization_id,
            "latency_ms": latency_ms,
            "timestamp": _now(),
            "meta": meta or {}
        })
        _save("request_log.json", logs)

    started = time.time()
    endpoint = "linear_transferIssue"

    try:
        if not isinstance(issue_id, str) or not re.match(r"^lin_iss_[0-9A-Z]{18,}$", issue_id):
            _log(endpoint, "error", meta={"error": "bad_issue_id"}, started=started)
            return _err("VALIDATION_ERROR", "issue_id is malformed.")
        if not isinstance(team_id, str) or not re.match(r"^lin_acct_[0-9A-Z]{18,}$", team_id):
            _log(endpoint, "error", meta={"error": "bad_team_id"}, started=started)
            return _err("VALIDATION_ERROR", "team_id is malformed.")

        orgs = _load("organizations.json")
        accts = _load("accounts.json")
        issues = _load("issues.json")
        activity = _load("issue_activity.json")

        if not isinstance(orgs, list) or not isinstance(accts, list) or not isinstance(issues, list) or not isinstance(activity, list):
            _log(endpoint, "error", meta={"error": "corrupt_store"}, started=started)
            return _err("CONFLICT", "Datastore is in an unexpected format.")

        # Resolve viewer + org context by searching for any valid active org with an active viewer.
        viewer = None
        org = None
        for o in orgs:
            if isinstance(o, dict) and o.get("status") in ("active", "suspended"):
                v = next((a for a in accts if isinstance(a, dict) and a.get("organization_id") == o.get("id") and a.get("entity_type") == "user" and a.get("status") == "active" and a.get("is_viewer") is True), None)
                if v:
                    viewer = v
                    org = o
                    break
        if not viewer or not org:
            _log(endpoint, "error", meta={"error": "no_viewer_context"}, started=started)
            return _err("UNAUTHORIZED", "No authenticated viewer context available.")

        # Write tools rejected if org is suspended.
        if org.get("status") != "active":
            _log(endpoint, "error", organization_id=org.get("id"), meta={"error": "org_not_active"}, started=started)
            return _err("UNAUTHORIZED", "Organization is not active for write operations.")

        # Find issue by id and ensure it belongs to org and is not deleted.
        issue = next((i for i in issues if isinstance(i, dict) and i.get("id") == issue_id), None)
        if not issue or issue.get("organization_id") != org.get("id") or issue.get("status") == "deleted":
            _log(endpoint, "error", organization_id=org.get("id"), meta={"error": "issue_not_found"}, started=started)
            return _err("NOT_FOUND", "Issue not found.")

        # Find destination team
        dest_team = next((a for a in accts if isinstance(a, dict) and a.get("id") == team_id and a.get("organization_id") == org.get("id") and a.get("entity_type") == "team" and a.get("status") == "active"), None)
        if not dest_team:
            _log(endpoint, "error", organization_id=org.get("id"), meta={"error": "team_not_found"}, started=started)
            return _err("NOT_FOUND", "Destination team not found.")

        from_team_id = issue.get("team_id")
        if from_team_id == dest_team.get("id"):
            _log(endpoint, "ok", organization_id=org.get("id"), meta={"idempotent": True}, started=started)
            return {"issue": issue}

        from_team = next((a for a in accts if isinstance(a, dict) and a.get("id") == from_team_id and a.get("entity_type") == "team"), None)
        from_identifier = issue.get("identifier")

        # Allocate next number per destination team
        max_num = 0
        for it in issues:
            if not isinstance(it, dict):
                continue
            if it.get("team_id") == dest_team.get("id") and it.get("status") != "deleted":
                n = it.get("number")
                if isinstance(n, int) and n > max_num:
                    max_num = n
        new_number = max_num + 1
        if new_number <= 0:
            _log(endpoint, "error", organization_id=org.get("id"), meta={"error": "bad_number_alloc"}, started=started)
            return _err("CONFLICT", "Could not allocate issue number.")

        team_key = dest_team.get("key")
        if not isinstance(team_key, str) or not team_key:
            _log(endpoint, "error", organization_id=org.get("id"), meta={"error": "dest_team_missing_key"}, started=started)
            return _err("CONFLICT", "Destination team is missing a key.")
        new_identifier = f"{team_key}-{new_number}"

        # Ensure new identifier unique in destination team among non-deleted
        if any(isinstance(it, dict) and it.get("team_id") == dest_team.get("id") and it.get("identifier") == new_identifier and it.get("status") != "deleted" for it in issues):
            _log(endpoint, "error", organization_id=org.get("id"), meta={"error": "identifier_conflict"}, started=started)
            return _err("CONFLICT", "Identifier conflict in destination team.")

        # Ensure state_id moved to a valid workflow_state in destination team.
        # Pick same state_category if possible, otherwise fallback to lowest position active state.
        cur_state_id = issue.get("state_id")
        cur_state = next((a for a in accts if isinstance(a, dict) and a.get("id") == cur_state_id and a.get("entity_type") == "workflow_state"), None)
        desired_cat = cur_state.get("state_category") if isinstance(cur_state, dict) else None

        dest_states = [a for a in accts if isinstance(a, dict) and a.get("entity_type") == "workflow_state" and a.get("team_id") == dest_team.get("id") and a.get("status") == "active"]
        if not dest_states:
            _log(endpoint, "error", organization_id=org.get("id"), meta={"error": "no_dest_states"}, started=started)
            return _err("CONFLICT", "Destination team has no active workflow states.")

        chosen_state = None
        if desired_cat:
            # pick lowest position in that category
            same_cat = [s for s in dest_states if s.get("state_category") == desired_cat]
            same_cat.sort(key=lambda x: (x.get("position") if isinstance(x.get("position"), int) else 10**9, x.get("id", "")))
            if same_cat:
                chosen_state = same_cat[0]
        if chosen_state is None:
            dest_states.sort(key=lambda x: (x.get("position") if isinstance(x.get("position"), int) else 10**9, x.get("id", "")))
            chosen_state = dest_states[0]

        # Apply transfer
        now = _now()
        issue["team_id"] = dest_team.get("id")
        issue["number"] = new_number
        issue["identifier"] = new_identifier
        issue["state_id"] = chosen_state.get("id")
        issue["updated_at"] = now

        # Record history event
        def _new_id(prefix):
            alpha = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
            t = int(time.time() * 1000)
            base = ""
            x = t
            while x > 0:
                base = alpha[x % 36] + base
                x //= 36
            base = (base or "0").rjust(18, "0")
            return f"{prefix}{base}"

        ev = {
            "id": _new_id("lin_act_"),
            "organization_id": org.get("id"),
            "entity_type": "issue_history_event",
            "status": "active",
            "issue_id": issue.get("id"),
            "user_id": viewer.get("id"),
            "body": None,
            "label_id": None,
            "related_issue_id": None,
            "relation_type": None,
            "event_type": "transferred",
            "event_payload": {
                "from_team_id": from_team_id,
                "to_team_id": dest_team.get("id"),
                "from_identifier": from_identifier,
                "to_identifier": new_identifier,
                "from_state_id": cur_state_id,
                "to_state_id": chosen_state.get("id")
            },
            "source_issue_id": None,
            "duplicate_issue_id": None,
            "created_at": now,
            "updated_at": now
        }
        activity.append(ev)

        _save("issues.json", issues)
        _save("issue_activity.json", activity)

        _log(endpoint, "ok", organization_id=org.get("id"), meta={"issue_id": issue.get("id")}, started=started)
        return {"issue": issue}
    except Exception as e:
        _log(endpoint, "error", meta={"error": "exception", "detail": str(e)}, started=started)
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

def linear_getIssueHistory(issue_id, limit=None, cursor=None, sort=None, event_type=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_getIssueHistory"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, organization_id=None, credential_id=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "lin_req_" + uuid.uuid4().hex.upper(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "credential_id": credential_id,
            "organization_id": organization_id,
        }
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(issue_id, str) or re.match(r"^lin_iss_[0-9A-Z]{18,}$", issue_id) is None:
        _log("error", message="issue_id malformed")
        return _err("VALIDATION_ERROR", "issue_id is malformed.")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("error", message="limit range")
            return _err("VALIDATION_ERROR", "limit is out of range (1-200).")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", message="cursor type")
        return _err("VALIDATION_ERROR", "cursor is malformed.")
    if sort is not None:
        if not isinstance(sort, str) or sort not in ("created_at", "-created_at"):
            _log("error", message="sort enum")
            return _err("VALIDATION_ERROR", "sort is invalid.")
    if event_type is not None:
        allowed = {
            "created", "updated", "state_changed", "priority_changed", "assignee_changed",
            "label_added", "label_removed", "archived", "unarchived", "transferred",
            "converted_to_subtask", "added_to_project", "added_to_cycle", "relation_created", "duplicated"
        }
        if not isinstance(event_type, str) or event_type not in allowed:
            _log("error", message="event_type enum")
            return _err("VALIDATION_ERROR", "event_type is invalid.")

    issues = _load("issues.json")
    activity = _load("issue_activity.json")
    if not isinstance(issues, list) or not isinstance(activity, list):
        _log("error", message="datastore corrupt")
        return _err("CONFLICT", "Datastore is in an unexpected format.")

    issue = next((i for i in issues if isinstance(i, dict) and i.get("id") == issue_id and i.get("status") != "deleted"), None)
    if not issue:
        _log("error", message="issue not found")
        return _err("NOT_FOUND", "Issue not found.")
    org_id = issue.get("organization_id")

    rows = []
    for r in activity:
        if not isinstance(r, dict):
            continue
        if r.get("entity_type") != "issue_history_event":
            continue
        if r.get("status") != "active":
            continue
        if r.get("issue_id") != issue_id:
            continue
        if event_type is not None and r.get("event_type") != event_type:
            continue
        rows.append(r)

    # sort by created_at
    reverse = (sort or "created_at") == "-created_at"
    def _dt(s):
        if not isinstance(s, str):
            return datetime.datetime.min
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return datetime.datetime.min
    rows.sort(key=lambda r: (_dt(r.get("created_at")), r.get("id") or ""), reverse=reverse)

    start_idx = 0
    if cursor:
        idx = next((i for i, r in enumerate(rows) if r.get("id") == cursor), None)
        if idx is None:
            _log("ok", organization_id=org_id, message="cursor not found")
            return {"nodes": [], "page_info": {"total": len(rows), "has_more": False, "next_cursor": None}}
        start_idx = idx + 1

    lim = limit if isinstance(limit, int) else 50
    page = rows[start_idx:start_idx + lim]
    next_cursor = page[-1].get("id") if len(page) == lim and (start_idx + lim) < len(rows) else None

    _log("ok", organization_id=org_id)
    return {"nodes": page, "page_info": {"total": len(rows), "has_more": next_cursor is not None, "next_cursor": next_cursor}}

def linear_getComments(issue_id, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0342000" if __import__("os").path.isdir("./environment_mix/0342000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b64d(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _b64e(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _log(endpoint, status, credential_id=None, organization_id=None, meta=None, started=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        ended = time.time()
        latency_ms = None
        if started is not None:
            latency_ms = int(round((ended - started) * 1000))
        logs.append({
            "id": f"lin_req_{int(ended*1000)}",
            "endpoint": endpoint,
            "status": status,
            "credential_id": credential_id,
            "organization_id": organization_id,
            "latency_ms": latency_ms,
            "timestamp": _now(),
            "meta": meta or {}
        })
        _save("request_log.json", logs)

    started = time.time()
    endpoint = "linear_getComments"

    try:
        if not isinstance(issue_id, str) or not re.match(r"^lin_iss_[0-9A-Z]{18,}$", issue_id):
            _log(endpoint, "error", meta={"error": "bad_issue_id"}, started=started)
            return _err("VALIDATION_ERROR", "issue_id does not match required format.")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log(endpoint, "error", meta={"error": "bad_limit"}, started=started)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
        if sort is None:
            sort = "created_at"
        if sort not in ("created_at", "-created_at"):
            _log(endpoint, "error", meta={"error": "bad_sort"}, started=started)
            return _err("VALIDATION_ERROR", "sort must be one of: created_at, -created_at.")

        orgs = _load("organizations.json")
        accts = _load("accounts.json")
        issues = _load("issues.json")
        activity = _load("issue_activity.json")

        if not isinstance(orgs, list) or not isinstance(accts, list) or not isinstance(issues, list) or not isinstance(activity, list):
            _log(endpoint, "error", meta={"error": "corrupt_store"}, started=started)
            return _err("CONFLICT", "Datastore is in an unexpected format.")

        viewer = None
        org = None
        for o in orgs:
            if isinstance(o, dict) and o.get("status") in ("active", "suspended"):
                v = next((a for a in accts if isinstance(a, dict) and a.get("organization_id") == o.get("id") and a.get("entity_type") == "user" and a.get("status") == "active" and a.get("is_viewer") is True), None)
                if v:
                    viewer = v
                    org = o
                    break
        if not viewer or not org:
            _log(endpoint, "error", meta={"error": "no_viewer_context"}, started=started)
            return _err("UNAUTHORIZED", "No authenticated viewer context available.")

        issue = next((i for i in issues if isinstance(i, dict) and i.get("id") == issue_id), None)
        if not issue or issue.get("organization_id") != org.get("id") or issue.get("status") == "deleted":
            _log(endpoint, "error", organization_id=org.get("id"), meta={"error": "issue_not_found"}, started=started)
            return _err("NOT_FOUND", "Issue not found.")

        rows = [r for r in activity if isinstance(r, dict) and r.get("entity_type") == "comment" and r.get("issue_id") == issue_id and r.get("status") == "active"]
        reverse = (sort == "-created_at")
        rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.min, r.get("id", "")), reverse=reverse)

        start_idx = 0
        if cursor:
            c = _b64d(cursor)
            if not isinstance(c, dict) or c.get("v") != 1 or c.get("sort") != sort:
                _log(endpoint, "error", organization_id=org.get("id"), meta={"error": "bad_cursor"}, started=started)
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            last_id = c.get("last_id")
            last_created_at = c.get("last_created_at")
            found = False
            for idx, r in enumerate(rows):
                if r.get("id") == last_id and r.get("created_at") == last_created_at:
                    start_idx = idx + 1
                    found = True
                    break
            if not found:
                _log(endpoint, "error", organization_id=org.get("id"), meta={"error": "cursor_not_found"}, started=started)
                return _err("VALIDATION_ERROR", "cursor is invalid or expired.")

        page = rows[start_idx:start_idx + limit]
        has_more = (start_idx + limit) < len(rows)
        next_cursor = None
        if has_more and page:
            last = page[-1]
            next_cursor = _b64e({"v": 1, "sort": sort, "last_id": last.get("id"), "last_created_at": last.get("created_at")})

        _log(endpoint, "ok", organization_id=org.get("id"), meta={"issue_id": issue_id, "count": len(page)}, started=started)
        return {
            "comments": page,
            "meta": {
                "total": len(rows),
                "limit": limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
                "sort": sort
            }
        }
    except Exception as e:
        _log(endpoint, "error", meta={"error": "exception", "detail": str(e)}, started=started)
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))
